argv:
[Console]::OutputEncoding = New-Object System.Text.UTF8Encoding($false)
Get-PnpDevice -PresentOnly -ErrorAction SilentlyContinue | Where-Object { $_.InstanceId -like 'USB*' } | ForEach-Object {
$pc=Get-PnpDeviceProperty -InstanceId $_.InstanceId -KeyName DEVPKEY_Device_ProblemCode -ErrorAction SilentlyContinue
$location=Get-PnpDeviceProperty -InstanceId $_.InstanceId -KeyName DEVPKEY_Device_LocationPaths -ErrorAction SilentlyContinue
[PSCustomObject]@{Status=$_.Status; ProblemCode=$pc.Data; Class=$_.Class; Name=$_.FriendlyName; InstanceId=$_.InstanceId; Location=$location.Data}
} | ConvertTo-Json -Depth 4
